/* ---- V313 ---- */

(function(){
'use strict';
if(window.__EMD_V313_BACKUP__)return;
window.__EMD_V313_BACKUP__=true;

var DB_KEY='emd_business_v1';
var SNAP_KEY='emd_business_v313_snapshot_v1';
var VERSION='EMD-BACKUP-V1';

function el(id){return document.getElementById(id)}
function status(msg,ok){
  var e=el('emd313Status'); if(!e)return;
  e.textContent=msg;
  e.style.background=ok===false?'#fff3f3':ok===true?'#effaf1':'#f3f6fa';
}
function readDB(){
  try{
    var raw=PLS.getItem(DB_KEY);
    if(!raw)throw new Error('لا توجد قاعدة بيانات محفوظة.');
    var db=JSON.parse(raw);
    return {raw:raw,db:db};
  }catch(e){throw new Error('تعذر قراءة قاعدة البيانات: '+e.message)}
}
function validateDB(db){
  if(!db||typeof db!=='object'||Array.isArray(db))return {ok:false,reason:'البيانات ليست كائنًا صالحًا.'};
  var missing=['orders','products','customers'].filter(function(k){return !Array.isArray(db[k])});
  if(missing.length)return {ok:false,reason:'حقول أساسية ناقصة: '+missing.join('، ')};
  return {ok:true,orders:db.orders.length,products:db.products.length,customers:db.customers.length};
}
async function digest(text){
  if(window.crypto&&crypto.subtle){
    var data=new TextEncoder().encode(text);
    var buf=await crypto.subtle.digest('SHA-256',data);
    return Array.from(new Uint8Array(buf)).map(function(x){return x.toString(16).padStart(2,'0')}).join('');
  }
  return 'no-digest';
}
async function exportBackup(){
  try{
    var x=readDB(),v=validateDB(x.db);
    if(!v.ok)throw new Error(v.reason);
    var backup={format:VERSION,createdAt:new Date().toISOString(),database:x.db};
    backup.sha256=await digest(JSON.stringify(backup.database));
    var blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json;charset=utf-8'});
    var a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download='EMD_Business_Backup_'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';
    document.body.appendChild(a);a.click();a.remove();
    setTimeout(function(){URL.revokeObjectURL(a.href)},1000);
    status('تم تصدير النسخة الاحتياطية بنجاح. عدد الطلبات: '+v.orders, true);
  }catch(e){status(e.message,false)}
}
async function snapshot(){
  try{
    var x=readDB(),v=validateDB(x.db);
    if(!v.ok)throw new Error(v.reason);
    var s={format:VERSION,createdAt:new Date().toISOString(),database:x.db,sha256:await digest(JSON.stringify(x.db))};
    PLS.setItem(SNAP_KEY,JSON.stringify(s));
    status('تم حفظ نقطة استعادة محلية بتاريخ '+new Date(s.createdAt).toLocaleString('ar-OM')+'.',true);
  }catch(e){status(e.message,false)}
}
async function restoreSnapshot(){
  try{
    var raw=PLS.getItem(SNAP_KEY);
    if(!raw)throw new Error('لا توجد نقطة استعادة محفوظة.');
    var s=JSON.parse(raw),v=validateDB(s.database);
    if(!v.ok)throw new Error('نقطة الاستعادة غير صالحة: '+v.reason);
    var check=await digest(JSON.stringify(s.database));
    if(s.sha256&&s.sha256!=='no-digest'&&check!==s.sha256)throw new Error('فشل التحقق من سلامة نقطة الاستعادة.');
    if(!confirm('سيتم استبدال البيانات الحالية بنقطة الاستعادة. هل تريد المتابعة؟'))return;
    PLS.setItem(DB_KEY,JSON.stringify(s.database));
    if(window.db)window.db=s.database;
    try{if(typeof window.render==='function')window.render()}catch(e){}
    try{if(typeof window.renderCustomers==='function')window.renderCustomers()}catch(e){}
    try{if(typeof window.renderProducts==='function')window.renderProducts()}catch(e){}
    status('تمت الاستعادة بنجاح. أعد فتح الصفحة إذا لاحظت شاشة لم تتحدث.',true);
  }catch(e){status(e.message,false)}
}
function importBackup(file){
  if(!file)return;
  var reader=new FileReader();
  reader.onload=async function(){
    try{
      var b=JSON.parse(reader.result);
      if(b.format!==VERSION)throw new Error('صيغة النسخة غير مدعومة.');
      var v=validateDB(b.database);
      if(!v.ok)throw new Error(v.reason);
      if(b.sha256&&b.sha256!=='no-digest'){
        var check=await digest(JSON.stringify(b.database));
        if(check!==b.sha256)throw new Error('فشل التحقق من سلامة ملف النسخة.');
      }
      if(!confirm('سيتم استبدال البيانات الحالية بالنسخة المستوردة. تأكد أنك أخذت نسخة حالية أولًا. متابعة؟'))return;
      PLS.setItem(DB_KEY,JSON.stringify(b.database));
      if(window.db)window.db=b.database;
      try{if(typeof window.render==='function')window.render()}catch(e){}
      try{if(typeof window.renderCustomers==='function')window.renderCustomers()}catch(e){}
      try{if(typeof window.renderProducts==='function')window.renderProducts()}catch(e){}
      status('تم استيراد النسخة بنجاح. الطلبات: '+v.orders+'، المنتجات: '+v.products+'، العملاء: '+v.customers+'.',true);
    }catch(e){status('فشل الاستيراد: '+e.message,false)}
  };
  reader.readAsText(file);
}
function validate(){
  try{
    var x=readDB(),v=validateDB(x.db);
    if(!v.ok){status(v.reason,false);return}
    status('البيانات سليمة مبدئيًا: '+v.orders+' طلب، '+v.products+' منتج، '+v.customers+' عميل.',true);
  }catch(e){status(e.message,false)}
}
function open(){var m=el('emdBackupV313');if(m)m.classList.add('show');validate()}
function close(){var m=el('emdBackupV313');if(m)m.classList.remove('show')}
window.EMDBackupV313={open:open,close:close,exportBackup:exportBackup,snapshot:snapshot,restoreSnapshot:restoreSnapshot,validate:validate};

function init(){
  var c=el('emdBackupV313').querySelector('.emd313-close'); if(c)c.onclick=close;
  el('emd313Export').onclick=exportBackup;
  el('emd313Snapshot').onclick=snapshot;
  el('emd313Restore').onclick=restoreSnapshot;
  el('emd313Validate').onclick=validate;
  el('emd313ClearSnapshot').onclick=function(){
    if(confirm('حذف نقطة الاستعادة الحالية؟')){PLS.removeItem(SNAP_KEY);status('تم حذف نقطة الاستعادة.',true)}
  };
  el('emd313Import').onclick=function(){el('emd313File').click()};
  el('emd313File').onchange=function(){importBackup(this.files&&this.files[0]);this.value=''};
}
init();
})();

